package com.priperi;
import android.content.Context;import androidx.test.core.app.ApplicationProvider;import org.json.*;import java.util.*;import java.util.concurrent.*;import static org.junit.Assert.*;
/** Authenticated malformed envelopes, generated only by disposable local accounts. */
final class PoisonInboxCase {
 static <T>T local(Repository.Job<T> job)throws Exception{CompletableFuture<T> f=new CompletableFuture<>();Repository.local(ApplicationProvider.getApplicationContext(),v->{try{return job.run(v);}catch(Throwable e){f.completeExceptionally(e);return null;}},f::complete,e->f.completeExceptionally(new AssertionError(e)));return f.get(90,TimeUnit.SECONDS);}
 static JSONObject send(Vault from,JSONObject to,boolean poison)throws Exception{JSONObject env=from.crypto().encrypt(Session.uid(),from.identity(),to,"Valid message after malformed batch");if(poison){env.put("ciphertext",Crypto.b64(new byte[128]));env.put("signature",from.crypto().sign((Crypto.context(env)+"\n"+env.getString("ciphertext")).getBytes(Crypto.UTF8)));}Repository.call(from,"sendMessage",new JSONObject().put("message",env));return env;}
 static void run()throws Exception{
  Context c=ApplicationProvider.getApplicationContext();assertTrue(BuildConfig.ALLOW_TEST_DEVICES);assertTrue(BuildConfig.BACKEND_URL.startsWith("http://10.0.2.2:"));Repository.reset();String suffix=UUID.randomUUID().toString().substring(0,8),pass="Poison-Test-Password-2026!";Vault bob=new Vault(c,"qa_poison_b_"+suffix),eve=new Vault(c,"qa_poison_e_"+suffix);
  try{local(v->{assertNull(v.account());Session.continueAccount(v,"qa_pa_"+suffix,pass);Session.continueAccount(bob,"qa_pb_"+suffix,pass);Session.continueAccount(eve,"qa_pe_"+suffix,pass);Session.restore(bob);send(bob,v.accountWithIdentity(),false);Session.restore(eve);send(eve,v.accountWithIdentity(),false);Session.restore(v);Repository.sync(v);Repository.approveContact(v,bob.account().getString("uid"));Repository.approveContact(v,eve.account().getString("uid"));
    for(Vault sender:new Vault[]{bob,eve}){Session.restore(sender);for(int i=0;i<25;i++)send(sender,v.accountWithIdentity(),true);}
    Session.restore(bob);JSONObject probe=bob.crypto().encrypt(Session.uid(),bob.identity(),v.accountWithIdentity(),"Signature boundary");probe.put("ciphertext",Crypto.b64(new byte[128]));
    java.security.GeneralSecurityException rejected=assertThrows(java.security.GeneralSecurityException.class,()->v.crypto().decrypt(v.account().getString("uid"),v.identity(),bob.accountWithIdentity(),probe));assertFalse("Invalid signature must not be acknowledged as authenticated bad ciphertext",rejected instanceof Crypto.SignedCiphertextInvalid);
    JSONObject good=send(bob,v.accountWithIdentity(),false);Session.restore(v);Repository.sync(v);Repository.sync(v);
    assertNotNull("Signed malformed ciphertext filled the first inbox page and starved a later valid message",v.message(good.getString("id")));JSONObject remaining=Repository.call(v,"syncInbox",new JSONObject());assertEquals("Malformed envelopes were not durably drained",0,remaining.getJSONArray("messages").length());
    String gid=UUID.randomUUID().toString();Session.restore(bob);GroupRepository.create(bob,gid,"Malformed group test");GroupRepository.action(bob,"inviteGroupMember",new JSONObject().put("groupId",gid).put("uid",v.account().getString("uid")).put("id",UUID.randomUUID().toString()));Session.restore(v);Repository.sync(v);String invite=v.groupInvites().getJSONObject(0).getString("id");GroupRepository.action(v,"acceptGroupInvite",new JSONObject().put("id",invite));Repository.sync(v);Session.restore(bob);Repository.sync(bob);
    JSONObject group= bob.group(gid),bad=bob.crypto().encryptGroup(Session.uid(),bob.identity(),v.accountWithIdentity(),"Unreadable group copy",UUID.randomUUID().toString(),System.currentTimeMillis(),gid,group.getInt("version"));bad.put("ciphertext",Crypto.b64(new byte[128]));bad.put("signature",bob.crypto().sign((Crypto.context(bad)+"\n"+bad.getString("ciphertext")).getBytes(Crypto.UTF8)));Repository.call(bob,"sendGroupMessage",new JSONObject().put("groupId",gid).put("messages",new JSONArray().put(bad)));Session.restore(v);Repository.sync(v);JSONObject unreadable=v.message(bad.getString("id"));assertNotNull(unreadable);assertTrue(unreadable.optBoolean("unsupported"));assertEquals("This message could not be decrypted.",unreadable.getString("body"));JSONObject after=Repository.call(v,"syncInbox",new JSONObject());assertEquals(0,after.getJSONObject("groupData").getJSONArray("messages").length());return true;});
  }finally{local(v->{Session.restore(bob);Session.resetAccount(bob);Session.restore(eve);Session.resetAccount(eve);Session.restore(v);Session.resetAccount(v);Repository.eraseLocal(v);return true;});bob.destroy();eve.destroy();Repository.reset();}
 }
}
